#!/usr/bin/env python3
"""Generate consistent English for location/door/save NAME pieces and write <MDT>_en.py RUN_TEXTS.

Map/dungeon MDTs are mostly just current-location (c000), door-target (d0xx) and save-location
(e001) names drawn from a shared place set. Hand-translating each invites drift, so we map them
from one table here. Glosses have table misses on the leading dungeon glyph (ア→射, ノ→年/歓,
ギ→恩, 遺→遣) and a leaked door-format byte (ニ/etc.) — so we match on the RELIABLE tail: the
dungeon by a stable substring and the room by its exact (correctly-decoded) suffix after "・".

Door labels are "<name>への" (to <name>); the trailing 'への' run is left to Step 3.
Names usually exceed the tiny equal-length box budget -> validate_en.py flags them OVER (Step-3
relocate the small MDT to grow, proven 003/012, or abbreviate). Full natural names kept here.

Usage:  python3 src/gen_names.py <MDT> [<MDT> ...]      (writes/overwrites script/<MDT>_en.py)
        python3 src/gen_names.py --print <MDT>           (dry run: print, don't write)
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

# Dungeon/area detected by a stable substring (avoids the mis-rendered leading glyph).
DUNGEON = [
    ("博物館", "Alent Museum"),      # アレント博物館 (Alent canon)
    ("の塔", "Gios Tower"),          # ギーオスの塔 (DM)
    ("遣跡", "Norza Ruins"),         # ノーザ遺跡 (遺→遣 miss) (DM)
    ("遺跡", "Norza Ruins"),
    ("油田", "Az Oil Field"),        # アズ油田 (DM)
    ("基地", "Garlyle Base"),        # 軍基地 / ガーライル基地
]
# Room/sub-area by exact suffix after "・" (these decode correctly).
ROOM = {
    "月のフロア": "Moon Floor", "星のフロア": "Star Floor", "太陽のフロア": "Sun Floor",
    "大地のフロア": "Earth Floor", "暗黒の部屋": "Dark Room", "回廊": "Corridor",
    "溶岩の谷": "Lava Valley", "空中回廊": "Sky Corridor", "外壁通路": "Outer Wall Passage",
    "屋上": "Rooftop", "ホール": "Hall", "シアター": "Theater", "資料室": "Archives",
    "図書室": "Library", "映写室": "Screening Room", "ゆうぎ場": "Game Room",
    "歴史の間": "Hall of History", "雲のかけ橋": "Cloud Bridge", "？？？の間": "??? Room",
    "第１ブロック": "Block 1", "第２ブロック": "Block 2", "入口": "Entrance",
    "デザートムーン部屋": "Desert Moon Room", "ライトニングスター部屋": "Lightning Star Room",
    "ブラッディローズ部屋": "Bloody Rose Room", "カエル部屋": "Frog Room",
    "将官の部屋": "Officers' Room", "１": "1F", "２": "2F", "３": "3F", "４": "4F",
}


def translate_location(jp: str) -> str | None:
    s = jp.strip().lstrip("ニ ")  # drop leaked door-format byte + spaces
    dungeon = next((en for sub, en in DUNGEON if sub in s), None)
    tail = s.split("・")[-1] if "・" in s else s
    room = ROOM.get(tail)
    if dungeon and "・" in s:
        return f"{dungeon}: {room}" if room else dungeon
    if dungeon and room is None:        # bare dungeon name, no room
        return dungeon
    if room:                            # room only (e.g. パームの街 handled elsewhere)
        return room
    return None                         # unknown -> caller leaves untranslated for manual pass


def gen(mdt: str) -> tuple[str, dict]:
    base = mdt.removesuffix(".MDT")
    d = json.load(open(ROOT / f"script/{base}/ja.json", encoding="utf-8"))
    run_texts: dict[str, dict[int, str]] = {}
    unknown = []
    for code, p in d["pieces"].items():
        if p["category"] not in ("location", "door", "save-location"):
            continue
        for r in p["text_runs"]:
            if "jp" not in r or r.get("glyphs", 0) < 2:
                continue
            if r["jp"].strip().lstrip("ニ ") in ("への", "ホへ", ""):
                continue  # directional particle run
            en = translate_location(r["jp"])
            if en:
                run_texts.setdefault(code, {})[r["i"]] = en
            else:
                unknown.append((code, r["i"], r["jp"]))
    return base, {"RUN_TEXTS": run_texts, "unknown": unknown}


def render(base: str, run_texts: dict) -> str:
    body = ["#!/usr/bin/env python3",
            f'"""English NAME translation of {base}.MDT — Step 2c (generated by src/gen_names.py).',
            "Keyed to script/" + base + "/ja.json. Schema: see EC0C_en.py. Names may exceed the box",
            'budget -> validate_en.py flags OVER (Step-3 relocate/abbreviate)."""', "",
            "SEG_TEXTS: dict[str, dict[int, str]] = {}", "",
            "RUN_TEXTS: dict[str, dict[int, str]] = {"]
    for code in sorted(run_texts):
        inner = ", ".join(f"{i}: {en!r}" for i, en in sorted(run_texts[code].items()))
        body.append(f'    "{code}": {{{inner}}},')
    body += ["}", ""]
    return "\n".join(body)


def main() -> int:
    args = sys.argv[1:]
    dry = "--print" in args
    targets = [a for a in args if a != "--print"]
    if not targets:
        sys.stderr.write(__doc__); return 2
    for mdt in targets:
        base, res = gen(mdt)
        text = render(base, res["RUN_TEXTS"])
        if dry:
            print(text)
        else:
            (ROOT / f"script/{base}_en.py").write_text(text, encoding="utf-8")
            print(f"wrote script/{base}_en.py "
                  f"({sum(len(v) for v in res['RUN_TEXTS'].values())} names)")
        if res["unknown"]:
            print(f"  UNKNOWN (manual): {res['unknown']}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
